        Product(name = "Snack bars", category = "Snacks and confectionery", symbol = "🥨", varieties = listOf("cereal", "protein", "fruit/nut"), sizes = listOf("As sold"), description = "Snacks and confectionery. Options: cereal; protein; fruit/nut.", researchShops = listOf("Lidl", "Aldi", "Dunnes Stores")),
        Product(name = "Speciality tea", category = "Snacks and confectionery", symbol = "🫖", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("SuperValu")),
        Product(name = "Sports / energy drinks", category = "Snacks and confectionery", symbol = "🛍", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("SuperValu")),
        Product(name = "Squash / dilutes / cordial", category = "Snacks and confectionery", symbol = "🛍", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("SuperValu")),
        Product(name = "Sweets", category = "Snacks and confectionery", symbol = "🍫", varieties = listOf("boiled", "gummy", "liquorice", "mints"), sizes = listOf("As sold"), description = "Snacks and confectionery. Options: boiled; gummy; liquorice; mints.", researchShops = listOf("Lidl", "Aldi", "Dunnes Stores", "SuperValu")),
        Product(name = "Toffee / fudge", category = "Snacks and confectionery", symbol = "🛍", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("Lidl", "Aldi", "Dunnes Stores")),
        Product(name = "Tortilla chips", category = "Snacks and confectionery", symbol = "🍟", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("Lidl", "Aldi", "Dunnes Stores")),
        Product(name = "Vegetable juice", category = "Snacks and confectionery", symbol = "🧃", varieties = listOf("As sold"), sizes = listOf("As sold"), description = "A snack or sweet treat from the grocery range.", researchShops = listOf("SuperValu"))
    )

    // Source lists sometimes describe the same general product with different
    // punctuation or wording. Keep one reusable product and retain every shop
    // association and option collected for that stable identity.
    val products: List<Product> = entries.groupBy { it.id }.values.map { matches ->
        val primary = matches.first()
        primary.copy(
            varieties = matches.flatMap { it.varieties }.distinct(),
            sizes = matches.flatMap { it.sizes }.distinct(),
            researchShops = matches.flatMap { it.researchShops }.distinct()
        )
    }
}
